CREATE TABLE IF NOT EXISTS gis_ambiguity_resolution_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_count INTEGER NOT NULL DEFAULT 0, high_confidence_count INTEGER NOT NULL DEFAULT 0, review_count INTEGER NOT NULL DEFAULT 0, unresolved_count INTEGER NOT NULL DEFAULT 0, activation_eligible BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());